-- Nexo Dev BCP | PostgreSQL | Datos ficticios de demostración.

-- CHAMA: pases en 30 días, CFR y ACCE en %, TMD en minutos.

-- ACCE mide cambios con evidencias completas en la demo.

BEGIN;

SET LOCAL client_encoding = 'UTF8';

SET LOCAL standard_conforming_strings = on;

CREATE SCHEMA nexo_dev_bcp;

SET LOCAL search_path = nexo_dev_bcp, pg_catalog;

CREATE TABLE cvt (
    codigo_aplicacion TEXT PRIMARY KEY NOT NULL,
    nombre_aplicacion TEXT NOT NULL,
    descripcion TEXT,
    po TEXT,
    lt TEXT,
    tribe_leader TEXT,
    ttl TEXT
);

CREATE TABLE jira_confluence (
    documento_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aplicacion TEXT NOT NULL REFERENCES cvt (codigo_aplicacion),
    audiencia TEXT NOT NULL CHECK (audiencia IN (
        'equipo_responsable', 'otros_equipos', 'ambos'
    )),
    tipo TEXT NOT NULL CHECK (tipo IN (
        'leccion_aprendida', 'regla_negocio', 'consideracion_interna',
        'lineamiento', 'politica', 'mejor_practica', 'modelo_operativo',
        'diagrama_arquitectura', 'diagrama_secuencia'
    )),
    titulo TEXT NOT NULL,
    contenido TEXT NOT NULL,
    url_origen TEXT,
    imagen_png BYTEA,
    herramienta_plataforma TEXT,
    CHECK (
        tipo <> 'modelo_operativo'
        OR (herramienta_plataforma IS NOT NULL AND length(trim(herramienta_plataforma)) > 0)
    )
);

CREATE TABLE jira_tickets (
    codigo_ticket TEXT PRIMARY KEY NOT NULL,
    codigo_aplicacion TEXT NOT NULL REFERENCES cvt (codigo_aplicacion),
    tipo TEXT NOT NULL CHECK (tipo IN ('WO', 'OCD')),
    ambiente TEXT NOT NULL CHECK (length(trim(ambiente)) > 0),
    url TEXT,
    titulo TEXT NOT NULL,
    descripcion TEXT NOT NULL,
    grupo_resolutor TEXT NOT NULL CHECK (grupo_resolutor IN (
        'Seguridad', 'Control de Accesos', 'AgileOPS', 'Base de Datos',
        'Soporte ITSM', 'Soporte Mainframe'
    )),
    estado TEXT NOT NULL DEFAULT 'Registrado'
        CHECK (estado IN ('Registrado', 'En Procesado', 'Terminado'))
);

CREATE TABLE jira_ops_genie (
    codigo_aplicacion TEXT NOT NULL REFERENCES cvt (codigo_aplicacion),
    soporte_1 TEXT,
    soporte_2 TEXT,
    soporte_3 TEXT,
    turno TEXT NOT NULL DEFAULT 'Titular',
    PRIMARY KEY (codigo_aplicacion, turno)
);

CREATE TABLE github (
    nombre_componente TEXT NOT NULL,
    codigo_aplicacion TEXT NOT NULL REFERENCES cvt (codigo_aplicacion),
    tipo TEXT NOT NULL CHECK (tipo IN ('componente', 'aprovisionamiento', 'contrato')),
    codigo_componente TEXT NOT NULL,
    codigo_fuente TEXT,
    PRIMARY KEY (codigo_aplicacion, tipo, codigo_componente)
);

CREATE TABLE portal_apis (
    api_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_aplicacion TEXT NOT NULL REFERENCES cvt (codigo_aplicacion),
    nombre_servicio TEXT NOT NULL,
    endpoint TEXT NOT NULL,
    metodo_http TEXT,
    contrato JSONB
);

CREATE TABLE chama (
    codigo_aplicacion TEXT NOT NULL REFERENCES cvt (codigo_aplicacion),
    estado_pases TEXT NOT NULL CHECK (estado_pases IN ('NORMAL', 'ALERTA', 'FREEZE')),
    indicador_pases DOUBLE PRECISION,
    indicador_cfr DOUBLE PRECISION,
    indicador_tmd DOUBLE PRECISION,
    indicador_acce DOUBLE PRECISION,
    corte TEXT NOT NULL DEFAULT 'Actual',
    PRIMARY KEY (codigo_aplicacion, corte)
);

CREATE INDEX idx_confluence_aplicacion_audiencia_tipo
    ON jira_confluence (codigo_aplicacion, audiencia, tipo);

CREATE INDEX idx_confluence_plataforma
    ON jira_confluence (herramienta_plataforma);

CREATE INDEX idx_portal_apis_aplicacion ON portal_apis (codigo_aplicacion);

CREATE INDEX idx_tickets_aplicacion ON jira_tickets (codigo_aplicacion);

